"use server";

import { generateSummary } from "@/ai/flows/generate-summary";
import { generateInteractiveQuizzes } from "@/ai/flows/generate-quizzes";
import { personalizeStudyPlan } from "@/ai/flows/personalize-study-plan";
import type { QuizQuestion, StudyGuide, Flashcard } from "@/lib/types";

// A simple parser for quiz questions generated by the AI.
// This is brittle and assumes a specific format.
function parseQuiz(quizText: string): QuizQuestion | null {
  try {
    const questionMatch = quizText.match(/^(.*?)\n/);
    const question = questionMatch ? questionMatch[1].replace(/^\d+\.\s*/, "").trim() : "";

    const optionsMatch = quizText.match(/([A-D]\))\s(.*?)\n/g);
    const options = optionsMatch ? optionsMatch.map(o => o.replace(/([A-D]\))\s/, "").trim()) : [];
    
    const answerMatch = quizText.match(/Answer:\s*([A-D])/);
    const correctLetter = answerMatch ? answerMatch[1] : "";
    
    if (!question || options.length < 2 || !correctLetter) {
      console.warn("Failed to parse quiz text:", quizText);
      return null;
    }
    
    const correctIndex = correctLetter.charCodeAt(0) - 'A'.charCodeAt(0);
    const correctAnswer = options[correctIndex];

    return { question, options, correctAnswer };
  } catch (error) {
    console.error("Error parsing quiz text:", quizText, error);
    return null;
  }
}

export async function generateStudyGuide(
  prevState: { studyGuide: StudyGuide | null; error?: string | null },
  formData: FormData
) {
  const material = formData.get("material") as string;
  if (!material || material.trim().length < 50) {
    return {
      studyGuide: null,
      error: "Please provide more substantial study material (at least 50 characters).",
    };
  }

  try {
    const [summaryResult, quizResult, planResult] = await Promise.all([
      generateSummary({ lectureNotes: material }),
      generateInteractiveQuizzes({
        learningMaterial: material,
        numberOfQuestions: 10,
      }),
      personalizeStudyPlan({
        studentId: "user-123",
        learningMaterials: material,
        quizScores: [0.5, 0.7, 0.6], // Mock data for initial plan
        flashcardPerformance: [0.8, 0.6, 0.9], // Mock data for initial plan
      }),
    ]);

    const quizzes: QuizQuestion[] = quizResult.quizzes
      .map(parseQuiz)
      .filter((q): q is QuizQuestion => q !== null);

    const flashcards: Flashcard[] = quizzes.map(q => ({
      front: q.question,
      back: q.correctAnswer,
    }));
      
    return {
      studyGuide: {
        summary: summaryResult.summary,
        quizzes: quizzes,
        flashcards: flashcards,
        studyPlan: planResult.personalizedStudyPlan,
      },
      error: null,
    };
  } catch (error) {
    console.error(error);
    return {
      studyGuide: null,
      error: "Failed to generate study guide. Please try again later.",
    };
  }
}
